module protocol::app;

use std::type_name::{Self, TypeName};
use sui::package;
use sui::table::{Self, Table};
use sui::dynamic_field;
use sui::vec_map::{Self, VecMap};

use protocol::error;
use protocol::market::{Self, Market, MarketConfiguration};
use protocol::referral::{Self, Referral};

// Increment this each time the protocol upgrades.
const CURRENT_VERSION: u64 = 1;

/// OTW for package initialization
public struct APP has drop {}

/// Administrative capability for protocol management
public struct AdminCap has key, store {
    id: UID,
}

/// Whitelist certain functions in the lending protocol to only certain packages
public struct PackageCallerCap has key, store {
    id: UID,
}

public struct ReferralKey has copy, drop, store {}
public struct PackageWhitestKey has copy, drop, store {}

/// Main protocol application state
public struct ProtocolApp has key, store {
    id: UID,
    version: u64,
    markets: Table<TypeName, ID>,

    // dynamic fields:
    // - referral (Referral)
    // - package_whitelist (VecSet<ID>)
}

/// Initialize the protocol
fun init(otw: APP, ctx: &mut TxContext) {
    package::claim_and_keep(otw, ctx);

    let (admin_cap, app) = create(ctx);

    transfer::transfer(admin_cap, ctx.sender());
    transfer::public_share_object(app);
}

fun create(ctx: &mut TxContext): (AdminCap, ProtocolApp) {
    // Create and transfer admin capability to deployer
    let admin_cap = AdminCap { id: object::new(ctx) };

    // Create and share protocol application object
    let mut app = ProtocolApp {
        id: object::new(ctx),
        version: CURRENT_VERSION,
        markets: table::new(ctx),
    };

    dynamic_field::add(&mut app.id, ReferralKey {}, referral::default(ctx));
    dynamic_field::add(&mut app.id, PackageWhitestKey {}, vec_map::empty<ID, u32>());

    (admin_cap, app)
}

// ==================== Public Getter Functions ====================
public fun permissions(self: &ProtocolApp, cap: &PackageCallerCap): u32 {
    let whitelist = dynamic_field::borrow<PackageWhitestKey, VecMap<ID, u32>>(&self.id, PackageWhitestKey {});

    let id = object::id(cap);
    assert!(whitelist.contains(&id), error::caller_not_whitelisted());

    *whitelist.get(&id)
}

public fun current_version(): u64 { CURRENT_VERSION }

public(package) fun ensure_version_matches(self: &ProtocolApp) {
    assert!(self.version == CURRENT_VERSION, error::version_mismatch());
}

public(package) fun migrate(self: &mut ProtocolApp): u64 {
    assert!(self.version < CURRENT_VERSION, error::version_mismatch());
    self.version = CURRENT_VERSION;

    CURRENT_VERSION
}

/// Get market configuration
public(package) fun get_market_config<MarketType>(
    self: &ProtocolApp,
    market: &Market<MarketType>,
): &MarketConfiguration {
    self.validate_market<MarketType>(market);
    market::market_config<MarketType>(market)
}

/// Get the ID of a registered market
public(package) fun get_market_id<MarketType>(self: &ProtocolApp): &ID {
    let key = type_name::with_defining_ids<MarketType>();
    assert!(self.markets.contains(key), error::market_not_found());
    table::borrow(&self.markets, key)
}

/// Check if a market is registered
public(package) fun is_market_registered<MarketType>(self: &ProtocolApp): bool {
    let key = type_name::with_defining_ids<MarketType>();
    self.markets.contains(key)
}

// /// Get protocol version
// public(package) fun get_version(self: &ProtocolApp): u64 {
//     self.version
// }

// ==================== Administrative Functions ====================
public(package) fun referral(self: &ProtocolApp): &Referral {
    dynamic_field::borrow<ReferralKey, Referral>(&self.id, ReferralKey {})
}

public(package) fun referral_mut(self: &mut ProtocolApp): &mut Referral {
    dynamic_field::borrow_mut<ReferralKey, Referral>(&mut self.id, ReferralKey {})
}

/// Register a new market type in the protocol, generally we dont remove markets
public(package) fun add_market<MarketType>(
    self: &mut ProtocolApp,
    id: ID,
) {
    let key = type_name::with_defining_ids<MarketType>();
    assert!(!self.markets.contains(key), error::market_already_exists());
    self.markets.add(key, id);
}

/// Validate that a market is registered and matches the provided market object
public(package) fun validate_market<MarketType>(self: &ProtocolApp, market: &Market<MarketType>) {
    let market_key = type_name::with_defining_ids<MarketType>();
    assert!(self.markets.contains(market_key), error::market_not_found());
    assert!(self.markets.borrow(market_key) == &object::id(market), error::invalid_market());
}

public(package) fun mint_cap(ctx: &mut TxContext): PackageCallerCap {
    PackageCallerCap { id: object::new(ctx) }
}

public(package) fun burn_cap(cap: PackageCallerCap) {
    let PackageCallerCap { id } = cap;
    object::delete(id);
}

public(package) fun whitelist_mut(self: &mut ProtocolApp): &mut VecMap<ID, u32> {
    dynamic_field::borrow_mut(&mut self.id, PackageWhitestKey {})
}

public(package) fun ensure_has_permission(self: &ProtocolApp, id: ID, what: u8) {
    let whitelist = dynamic_field::borrow<PackageWhitestKey, VecMap<ID, u32>>(&self.id, PackageWhitestKey {});

    assert!(whitelist.contains(&id), error::caller_not_whitelisted());

    let permission = *whitelist.get(&id);

    let mask = 1u32 << what;
    let has_permission = (permission & mask) != 0;

    assert!(has_permission, error::caller_has_no_permission());
}

#[test_only]
public fun init_t(ctx: &mut TxContext): (AdminCap, ProtocolApp) {
    create(ctx)
}

